{"content":"import React, { useState } from "react";
import { AppShell, Header, Footer, Page, Card, Button } from "@codesweep-ai/ui";
import "@codesweep-ai/ui/styles/core.css";
import "@codesweep-ai/ui/styles/components/app-shell.css";
import "@codesweep-ai/ui/styles/components/button.css";
import "@codesweep-ai/ui/styles/components/card.css";
import "@codesweep-ai/ui/styles/components/page.css";

const colourMap = [
  { label: "Blue", token: "var(--color-info)" },
  { label: "Green", token: "var(--color-success)" },
  { label: "Amber", token: "var(--color-warning)" },
  { label: "Red", token: "var(--color-error)" },
];

export default function App() {
  const [colour, setColour] = useState(colourMap[0].token);

  return (
    <AppShell>
      <Header title="Hello App" />
      <Page>
        <Card style={{ textAlign: "center" }}>
          <h1
            style={{
              fontSize: "var(--font-size-prose-h1)",
              fontWeight: "var(--font-weight-bold)",
              textAlign: "center",
              color: colour,
              marginBottom: "var(--space-4)",
            }}
          >
            Hello, world!
          </h1>
          <div
            style={{
              display: "flex",
              justifyContent: "center",
              gap: "var(--space-2)",
            }}
          >
            {colourMap.map(({ label, token }) => (
              <Button
                key={label}
                variant={colour === token ? "primary" : "secondary"}
                onClick={() => setColour(token)}
              >
                {label}
              </Button>
            ))}
          </div>
        </Card>
      </Page>
      <Footer style={{ textAlign: "center" }}>
        Built with @codesweep-ai/ui
      </Footer>
    </AppShell>
  );
}
